WITH monthly AS (
 SELECT s.store_name AS 门店, SUBSTR(o.order_date,1,7) AS 月份, SUM(o.amount) AS 商品总额
 FROM clean_orders o JOIN stores s USING(store_id)
 GROUP BY s.store_id, s.store_name, SUBSTR(o.order_date,1,7)
), compared AS (
 SELECT *, LAG(商品总额) OVER(PARTITION BY 门店 ORDER BY 月份) AS 上月商品总额 FROM monthly
)
SELECT 门店,月份,商品总额 AS 本月商品总额,上月商品总额,
 ROUND(100.0*(商品总额-上月商品总额)/NULLIF(上月商品总额,0),2) AS 环比_pct
FROM compared ORDER BY 门店,月份;

SELECT row_id AS 原始行, order_id AS 订单号, store_id AS 门店ID,
 product_id AS 商品ID, amount AS 金额, issue AS 排除原因
FROM flagged_orders WHERE issue IS NOT NULL ORDER BY row_id;
